<style lang="scss" src="./modal.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import { MountingPortal } from "portal-vue";
import Icon from "../icon/icon";
import { IconShape } from "../icon/icon.constants";
import Button from "../button/button";
import { ButtonMode, ButtonSize } from "../button/button.constants";
import {
  ModalWidth,
  ModalWidthValues,
  ModalElevation,
  ModalElevationValues,
} from "./modal.constants";
import ScrollView from "../scroll-view/scroll-view";
import { has } from "../../util/has";

/**
 * Displays a modal with content specific to Sharing via media platforms.
 */
@Component({
  components: {
    MountingPortal,
    Icon,
    Button,
    ScrollView,
  },
})
export default class Modal extends Vue {
  /** Custom width of the modal content */
  @Prop({
    type: String,
    default: ModalWidth.MEDIUM,
    validator: has(ModalWidthValues),
    required: false,
  })
  width;

  /** Custom z-index of the modal for layering */
  @Prop({
    type: String,
    default: ModalElevation.BACK,
    validator: has(ModalElevationValues),
    required: false,
  })
  elevation;

  /** The title to display at the top of the modal */
  @Prop({ type: String }) title;

  /** Buttons to display in the left side of the Footer of the modal */
  @Prop({
    type: Array,
    default: () => [],
  })
  rightButtons;

  /** Buttons to display in the right side of the Footer of the modal */
  @Prop({
    type: Array,
    default: () => [],
  })
  leftButtons;

  /** Remove content padding */
  @Prop({
    type: Boolean,
    default: false,
  })
  noPadding;

  /** Remove content padding */
  @Prop({ type: String }) text;

  /** Disable closing modal on overlay click */
  @Prop({ type: Boolean, default: false }) disableCloseOnOverlayClick;

  /** Removes close button */
  @Prop({ type: Boolean, default: false }) disableCloseButton;

  // Enums
  IconShape = IconShape;
  ButtonMode = ButtonMode;
  ButtonSize = ButtonSize;

  handleClick(click, side, index) {
    /**
     * Fires when you click on a button. This fires the event with the index of
     * the button clicked which corresponds to the buttons prop.
     *
     * @event click {{number, string}}
     */
    if (click) {
      click(this.handleClose);
    }
    this.$emit("click", { index, side });
  }

  handleClose() {
    /**
     * Emitted when it is detected that the user wishes for this modal to be
     * closed.
     *
     * @event close
     */
    this.$emit("close");
  }

  handleCloseOutside(e) {
    if (!this.disableCloseOnOverlayClick) {
      if (e.target !== this.$refs.container) return;

      this.handleClose();
      e.stopPropagation();
      e.preventDefault();
    }
  }
}
</script>

<template>
  <transition appear name="Modal--fade">
    <div
      :class="['Modal', elevation]"
      ref="container"
      @click="handleCloseOutside"
    >
      <div :class="['Modal__Content', width, elevation]">
        <Icon
          v-if="!disableCloseButton"
          class="Modal__Close"
          :shape="IconShape.CLOSE"
          :size="24"
          @click="handleClose"
        />
        <div v-if="title" class="Modal__Head">
          <span>{{ title }}</span>
        </div>
        <div :class="['Modal__Body', { 'Modal__Body--NoTitle': !title }]">
          <ScrollView class="Modal__Scroll">
            <div
              :class="[
                'Modal__BodyContent',
                {
                  'Modal__BodyContent--NoPadding': noPadding,
                  'Modal__BodyContent--NoTitle': !title,
                },
              ]"
            >
              <slot />
              <div v-if="text">
                {{ text }}
              </div>
            </div>
          </ScrollView>
        </div>

        <!-- Show the footer if there are things to show -->
        <div
          class="Modal__Footer"
          v-if="
            $slots['modal-footer-left'] ||
              $slots['modal-footer-right'] ||
              (rightButtons && rightButtons.length > 0) ||
              (leftButtons && leftButtons.length > 0)
          "
        >
          <div class="Modal__Buttons-left">
            <slot v-if="$slots['modal-footer-left']" name="modal-footer-left" />
            <template v-else-if="leftButtons && leftButtons.length > 0">
              <Button
                v-for="(button, i) in leftButtons"
                :key="button.label"
                :mode="button.mode"
                :size="ButtonSize.SMALL"
                :label="button.label"
                :background-color="button.backgroundColor"
                :label-color="button.labelColor"
                :force-state="button.forceState"
                @click="handleClick(button.click, 'left', i)"
              />
            </template>
          </div>
          <div class="Modal__Buttons-right">
            <slot
              v-if="$slots['modal-footer-right']"
              name="modal-footer-right"
            />
            <template v-else-if="rightButtons && rightButtons.length > 0">
              <Button
                v-for="(button, i) in rightButtons"
                :key="button.label"
                :mode="button.mode"
                :size="ButtonSize.SMALL"
                :label="button.label"
                :background-color="button.backgroundColor"
                :label-color="button.labelColor"
                :force-state="button.forceState"
                @click="handleClick(button.click, 'right', i)"
              />
            </template>
          </div>
        </div>
      </div>
    </div>
  </transition>
</template>
